{
  "findings": [
    {
      "check_id": "CKV2_AWS_22",
      "title": "Ensure an IAM User does not have access to the console",
      "resource": "aws_iam_user.fp3-deny-iam-user",
      "severity": "MEDIUM",
      "explanation": "The IAM user 'fp3-deny-iam-user' is created without explicitly disabling console access, potentially allowing console login."
    }
  ],
  "patched_code": "resource "aws_iam_user" "fp3-deny-iam-user" {
  name          = "fp3-deny-iam-user"
  path          = "/"
  force_destroy = true
}

resource "aws_iam_user_login_profile" "fp3-deny-iam-user" {
  user    = aws_iam_user.fp3-deny-iam-user.name
  pgp_key = "keybase:somekeybaseusername"
  lifecycle {
    ignore_changes = [password_length, password_reset_required, pgp_key]
  }
}

resource "aws_iam_access_key" "fp3-deny-iam-user" {
  user = aws_iam_user.fp3-deny-iam-user.name
  status = "Inactive"
}",
  "fix_summary": "Added aws_iam_user_login_profile with pgp_key and aws_iam_access_key with Inactive status to prevent console access and ensure access keys are not active by default."
}
